package io.opentelemetry.instrumentation.runtimetelemetry.internal;

import static java.util.concurrent.TimeUnit.SECONDS;

import io.opentelemetry.api.metrics.Meter;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Predicate;
import java.util.function.Supplier;
import javax.annotation.Nullable;

/**
 * Registers measurements that generate metrics about CPU. The metrics generated by this class
 * follow <a
 * href="https://github.com/open-telemetry/semantic-conventions/blob/main/docs/runtime/jvm-metrics.md">the
 * stable JVM metrics semantic conventions</a>.
 *
 * <p>This class is internal and is hence not for public use. Its APIs are unstable and can change
 * at any time.
 */
public class Cpu {

  // Visible for testing
  static final Cpu INSTANCE = new Cpu();

  private static final double NANOS_PER_S = SECONDS.toNanos(1);

  /** Register observers for java runtime CPU metrics. */
  public static List<AutoCloseable> registerObservers(Meter meter) {
    return registerObservers(meter, unused -> true);
  }

  static List<AutoCloseable> registerObservers(Meter meter, Predicate<String> metricNamePredicate) {
    return registerObservers(meter, metricNamePredicate, unused -> {});
  }

  static List<AutoCloseable> registerObservers(
      Meter meter, Predicate<String> metricNamePredicate, Consumer<String> registered) {
    return registerObservers(
        meter,
        CpuMethods.processCpuTime(),
        CpuMethods.processCpuUtilization(),
        metricNamePredicate,
        registered);
  }

  // Visible for testing
  List<AutoCloseable> registerObservers(
      Meter meter,
      @Nullable Supplier<Long> processCpuTime,
      @Nullable Supplier<Double> processCpuUtilization) {
    return registerObservers(
        meter, processCpuTime, processCpuUtilization, unused -> true, unused -> {});
  }

  // Visible for testing
  static List<AutoCloseable> registerObservers(
      Meter meter,
      @Nullable Supplier<Long> processCpuTime,
      @Nullable Supplier<Double> processCpuUtilization,
      Predicate<String> metricNamePredicate,
      Consumer<String> registered) {
    List<AutoCloseable> observables = new ArrayList<>();

    if (processCpuTime != null && metricNamePredicate.test("jvm.cpu.time")) {
      observables.add(
          meter
              .counterBuilder("jvm.cpu.time")
              .ofDoubles()
              .setDescription("CPU time used by the process as reported by the JVM.")
              .setUnit("s")
              .buildWithCallback(
                  observableMeasurement -> {
                    Long cpuTimeNanos = processCpuTime.get();
                    if (cpuTimeNanos != null && cpuTimeNanos >= 0) {
                      observableMeasurement.record(cpuTimeNanos / NANOS_PER_S);
                    }
                  }));
      registered.accept("jvm.cpu.time");
    }
    if (processCpuUtilization != null && metricNamePredicate.test("jvm.cpu.recent_utilization")) {
      observables.add(
          meter
              .gaugeBuilder("jvm.cpu.recent_utilization")
              .setDescription("Recent CPU utilization for the process as reported by the JVM.")
              .setUnit("1")
              .buildWithCallback(
                  observableMeasurement -> {
                    Double cpuUsage = processCpuUtilization.get();
                    if (cpuUsage != null && cpuUsage >= 0) {
                      observableMeasurement.record(cpuUsage);
                    }
                  }));
      registered.accept("jvm.cpu.recent_utilization");
    }

    return observables;
  }

  protected Cpu() {}
}
